    const form = document.getElementById('quiz-form');
    const resultMessage = document.getElementById('result-message');

    // Expected answers for each question
    const expectedAnswers = {
        q1: ['javascript', 'typescript'], // Web development languages
        q2: ['c', 'rust', 'cpp'],         // Systems programming languages
        q3: ['python', 'javascript', 'ruby'] // Dynamically typed languages
    };

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get all selected answers
        const selectedAnswers = {
            q1: [],
            q2: [],
            q3: []
        };

        // Collect checked boxes for each question
        document.querySelectorAll('input[type="checkbox"]:checked').forEach(checkbox => {
            const question = checkbox.name;
            const value = checkbox.value;
            selectedAnswers[question].push(value);
        });

        // Validate answers
        let score = 0;
        let totalQuestions = 3;
        let feedback = [];

        for (let q = 1; q <= 3; q++) {
            const question = `q${q}`;
            const selected = selectedAnswers[question];
            const expected = expectedAnswers[question];

            // Check if selected answers match expected answers exactly
            const isCorrect = arraysEqual(selected.sort(), expected.sort());

            if (isCorrect) {
                score++;
                feedback.push(`✓ Question ${q}: Correct`);
            } else {
                feedback.push(`✗ Question ${q}: Incorrect - Expected: ${expected.join(', ')}`);
            }
        }

        // Display result
        const percentage = Math.round((score / totalQuestions) * 100);
        const resultText = `You scored ${score}/${totalQuestions} (${percentage}%)<br>${feedback.join('<br>')}`;

        resultMessage.innerHTML = resultText;
        resultMessage.classList.remove('error', 'success');

        if (score >= 2) {
            resultMessage.classList.add('success');
        } else {
            resultMessage.classList.add('error');
        }
    });

